<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Faculty');check_csrf();$u=current_user();$f=db()->prepare('SELECT id FROM faculty WHERE user_id=?');$f->execute([$u['id']]);$fid=(int)$f->fetchColumn();$subs=db()->prepare('SELECT s.id,s.code,s.name FROM subjects s JOIN faculty_subjects fs ON fs.subject_id=s.id WHERE fs.faculty_id=?');$subs->execute([$fid]);if($_SERVER['REQUEST_METHOD']==='POST'){$q=db()->prepare('INSERT INTO assignments(subject_id,faculty_id,title,description,deadline,max_marks,status) VALUES(?,?,?,?,?,?,?)');$q->execute([(int)$_POST['subject_id'],$fid,trim($_POST['title']),trim($_POST['description']),$_POST['deadline'],(float)$_POST['max_marks'],'published']);AuditService::log('CREATE','assignments',(int)db()->lastInsertId(),'Assignment created');$_SESSION['flash']=['success','Assignment published'];redirect('assignments.php');}page_top('Assignment Studio');flash();?><div class='card p-4 mb-3'><form method='post' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><div class='col-md-6'><label>Subject</label><select name='subject_id' class='form-select'><?php foreach($subs as $s):?><option value='<?=e($s['id'])?>'><?=e($s['code'].' · '.$s['name'])?></option><?php endforeach;?></select></div><div class='col-md-6'><label>Title</label><input name='title' class='form-control' required></div><div class='col-12'><label>Description</label><textarea name='description' class='form-control'></textarea></div><div class='col-md-4'><label>Deadline</label><input type='datetime-local' name='deadline' class='form-control' required></div><div class='col-md-3'><label>Max marks</label><input type='number' name='max_marks' class='form-control' value='10'></div><div class='col-12'><button class='btn btn-primary'>Publish Assignment</button></div></form></div><div class='card p-3 table-responsive'><table class='table'><tr><th>Title</th><th>Deadline</th><th>Marks</th><th>Status</th></tr><?php $q=db()->prepare('SELECT * FROM assignments WHERE faculty_id=? AND deleted_at IS NULL ORDER BY id DESC');$q->execute([$fid]);foreach($q as $a):?><tr><td><?=e($a['title'])?></td><td><?=e($a['deadline'])?></td><td><?=e($a['max_marks'])?></td><td><span class='badge bg-primary'><?=e($a['status'])?></span></td></tr><?php endforeach;?></table></div><?php page_bottom();